    if (blocked) continue;
    const car = createVehicle(traffic.city, x, z, heading, TRAFFIC_KINDS[r.int(TRAFFIC_KINDS.length)], r);
    car.driver = 'npc';
    car.lane = lane;
    car.laneIndex = traffic.lanes.indexOf(lane);
